(assert (= "1.12.6" (clojure-version)))
(def ^{:redef true :arglists '(^long [])} raw-long (fn ^long [] (identity 4)))
(def run-long (fn [] [(try (quot (raw-long) 2) (catch Throwable e :error)) (try (rem (raw-long) 2) (catch Throwable e :error)) (try (abs (raw-long)) (catch Throwable e :error)) (try (unchecked-add (raw-long) 1) (catch Throwable e :error)) (try (unchecked-negate (raw-long)) (catch Throwable e :error))]))
(def ^{:redef true :arglists '(^double [])} raw-double (fn ^double [] (identity 4.0)))
(def run-double (fn [] [(try (quot (raw-double) 2) (catch Throwable e :error)) (try (rem (raw-double) 2) (catch Throwable e :error)) (try (abs (raw-double)) (catch Throwable e :error)) (try (unchecked-add (raw-double) 1) (catch Throwable e :error)) (try (unchecked-negate (raw-double)) (catch Throwable e :error))]))
(prn "(vector (run-long) (with-redefs [raw-long (fn [] (identity 3.5))] (run-long)))" (pr-str (vector (run-long) (with-redefs [raw-long (fn [] (identity 3.5))] (run-long)))))
(prn "(vector (run-double) (with-redefs [raw-double (fn [] (identity 5))] (run-double)))" (pr-str (vector (run-double) (with-redefs [raw-double (fn [] (identity 5))] (run-double)))))
(prn "(with-redefs [raw-long (fn [] :bad) raw-double (fn [] nil)] [(run-long) (run-double)])" (pr-str (with-redefs [raw-long (fn [] :bad) raw-double (fn [] nil)] [(run-long) (run-double)])))
(prn "(with-redefs [raw-long (fn [] (identity -0.0))] (run-long))" (pr-str (with-redefs [raw-long (fn [] (identity -0.0))] (run-long))))
(def observe-long (fn [] (try (raw-long) (catch Throwable e [(str (class e)) (ex-message e)]))))
(prn :long-replacement-cause (with-redefs [raw-long (fn [] (identity 3.5))] (observe-long)))
(def observe-double (fn [] (try (raw-double) (catch Throwable e [(str (class e)) (ex-message e)]))))
(prn :double-replacement-cause (with-redefs [raw-double (fn [] (identity 5))] (observe-double)))
